from __future__ import annotations

WEBAPP_V2_HTML = r"""<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>FULL MYSQL V2</title>
<style>
:root{color-scheme:light dark;--bg:#f5f7fa;--card:#fff;--text:#101828;--muted:#667085;--line:#e4e7ec;--a:#175cd3;--ok:#067647;--bad:#b42318;--warn:#b54708;--sale:#c11574}
@media(prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--text:#f3f4f6;--muted:#98a2b3;--line:#2c313a;--a:#84adff;--ok:#47cd89;--bad:#f97066;--warn:#fdb022;--sale:#f670c7}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.45 system-ui,sans-serif;padding-bottom:74px}.w{max-width:1040px;margin:auto;padding:12px}.top{position:sticky;top:0;z-index:10;background:color-mix(in srgb,var(--bg) 94%,transparent);backdrop-filter:blur(10px);padding:8px 0}.brand{display:flex;justify-content:space-between;align-items:flex-end}.brand h1{font-size:20px;margin:0}.ver,.meta,.msg,.small{font-size:12px;color:var(--muted)}
button,input,select{font:inherit;color:var(--text);background:var(--card);border:1px solid var(--line);border-radius:11px;padding:11px}button{font-weight:750;cursor:pointer}button.primary{background:var(--a);color:#fff;border-color:transparent}input,select{width:100%}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.grow{flex:1}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;margin:10px 0}.result{cursor:pointer}.result:hover{border-color:var(--a)}.name{font-weight:800}.screen{display:none}.screen.on{display:block}.head{display:flex;gap:8px;align-items:center;margin:10px 0}.title{font-size:19px;font-weight:820}.back{width:auto;padding:7px 10px}
.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}@media(min-width:760px){.grid{grid-template-columns:repeat(4,minmax(0,1fr))}.form{grid-template-columns:repeat(2,1fr)}}.m{border:1px solid var(--line);border-radius:11px;padding:9px}.m .k{font-size:11px;color:var(--muted)}.m .v{font-size:17px;font-weight:800;overflow-wrap:anywhere}.form{display:grid;grid-template-columns:1fr;gap:8px}label{display:block;font-size:11px;color:var(--muted);margin-bottom:3px}.pill{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:3px 7px;font-size:11px}.ok{color:var(--ok)}.bad{color:var(--bad)}.warn{color:var(--warn)}.sale{color:var(--sale)}
.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.actions button{min-height:54px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:7px 5px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted)}.scroll{overflow:auto}.hide{display:none!important}.chart{width:100%;height:290px;border:1px solid var(--line);border-radius:12px}.big{font-size:27px;font-weight:850}.order{border-left:4px solid var(--a)}.promo{border:1px solid var(--line);border-radius:10px;padding:8px;margin:7px 0}.nav{position:fixed;left:0;right:0;bottom:0;z-index:20;background:var(--card);border-top:1px solid var(--line);padding:6px}.navin{max-width:1040px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr)}.nav button{border:0;background:transparent;color:var(--muted);font-size:11px}.nav button.on{color:var(--a)}
</style></head><body><div class="w">
<div class="top"><div class="brand"><h1>FULL MYSQL</h1><div class="ver">Web App V2 · v7.0.111</div></div><div class="msg">CORE · ORDERING · PI</div></div>

<section id="core" class="screen on"><div class="head"><div><div class="title">🔎 CORE</div><div class="meta">Search item name, Family Article, Article, or UPC.</div></div></div><div class="row"><input id="cq" class="grow" placeholder="Search item"><button id="cs" class="primary">Search</button></div><div id="cmsg" class="msg"></div><div id="cres"></div></section>

<section id="family" class="screen"><div class="head"><button class="back" data-go="core">←</button><div><div id="ft" class="title"></div><div id="fs" class="meta"></div></div></div><div id="fsummary"></div><div class="card"><b>Related UPCs</b><div class="scroll"><table><thead><tr><th>Item</th><th>Status</th><th>Price</th><th>Type</th><th>7D</th><th>28D</th></tr></thead><tbody id="fu"></tbody></table></div></div></section>

<section id="upc" class="screen"><div class="head"><button class="back" id="ub">←</button><div><div id="ut" class="title"></div><div id="us" class="meta"></div></div></div><div id="usum" class="card"></div><div class="actions"><button id="uf">Family Article</button><button id="upr">Price</button><button id="uo">Ordering</button></div></section>

<section id="price" class="screen"><div class="head"><button class="back" data-go="upc">←</button><div><div id="pt" class="title"></div><div id="ps" class="meta"></div></div></div><div id="pc"></div><div class="card"><b>Price vs Sales Trend</b><canvas id="chart" class="chart"></canvas><div class="small">Price and Qty use completed canonical sales-data dates only. Missing source dates are gaps, not zero.</div></div><div class="card"><b>Historical SALE Promotions</b><div id="ph"></div></div></section>

<section id="corder" class="screen"><div class="head"><button class="back" data-go="upc">←</button><div><div id="cot" class="title"></div><div id="cos" class="meta"></div></div></div><div class="card"><div class="form"><div><label>Ordering Date</label><input id="cod" type="date"></div><div><label>Expected Delivery Date</label><input id="cdd" type="date"></div><div><label>Context</label><select id="cop"><option value="0">Regular</option><option value="1">Promotion Involved</option></select></div></div><div id="cpf" class="form hide" style="margin-top:8px"><div><label>Promotion Start</label><input id="cps" type="date"></div><div><label>Promotion End</label><input id="cpe" type="date"></div><div><label>Promotion Price</label><input id="cpp"></div></div><div id="cohist"></div><button id="coa" class="primary" style="margin-top:9px">Analyze</button></div><div id="coout"></div></section>

<section id="ordering" class="screen"><div class="head"><div><div class="title">📦 ORDERING</div><div class="meta">Family-level Fresh / Frozen ordering suggestions.</div></div></div><div class="card"><div class="form"><div><label>Fresh or Frozen</label><select id="ot"><option>FRESH</option><option>FROZEN</option></select></div><div><label>Ordering Date</label><input id="od" type="date"></div><div><label>Expected Delivery</label><input id="dd" type="date"></div><div><label>Context</label><select id="op"><option value="0">Regular</option><option value="1">Promotion Involved</option></select></div></div><div id="opa" class="hide"><div class="form" style="margin-top:8px"><div><label>Promotion Start</label><input id="ops" type="date"></div><div><label>Promotion End</label><input id="ope" type="date"></div></div><div class="row" style="margin-top:8px"><input id="oiq" class="grow" placeholder="Search promotion item"><button id="ois">Search</button></div><div id="oim" class="msg"></div><div id="oir"></div><div id="oil"></div><div id="ohist"></div></div><button id="ogen" class="primary" style="margin-top:10px">Generate Suggestions</button><div id="omsg" class="msg"></div></div><div id="ores"></div></section>

<section id="pi" class="screen"><div class="head"><div><div class="title">🧮 PI</div><div class="meta">Physical Inventory · True Stock adjustment.</div></div></div><div class="row"><input id="piq" class="grow" placeholder="Search item / family / article / UPC"><button id="pis" class="primary">Search</button></div><div id="pim" class="msg"></div><div id="pir"></div></section>

<section id="pid" class="screen"><div class="head"><button class="back" data-go="pi">←</button><div><div id="pit" class="title"></div><div id="pisub" class="meta"></div></div></div><div id="pisum"></div><div class="card"><b>Apply True Stock</b><div class="form" style="margin-top:8px"><div><label>True Stock</label><input id="pqty"></div><div><label>UOM</label><input id="puom" readonly></div></div><div style="margin-top:8px"><label>Note</label><input id="pnote"></div><button id="papply" class="primary" style="margin-top:9px">Apply True Stock</button><div id="pamsg" class="msg"></div></div><div class="card"><b>PI History</b><div class="scroll"><table><thead><tr><th>Time</th><th>System</th><th>True</th><th>Diff</th><th>Status</th><th>Note</th></tr></thead><tbody id="pih"></tbody></table></div></div></section>
</div>

<nav class="nav"><div class="navin"><button data-main="core" class="on">🔎<br>CORE</button><button data-main="ordering">📦<br>ORDERING</button><button data-main="pi">🧮<br>PI</button></div></nav>

<script>
const $=x=>document.getElementById(x),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>{if(v===null||v===undefined||v==='')return '—';let n=Number(v);return Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d}):String(v)},money=v=>v===null||v===undefined?'—':'$'+fmt(v,2);
const today=()=>new Date().toLocaleDateString('en-CA'),nextwd=(s,t)=>{let d=new Date(s+'T12:00:00'),x=(t-d.getDay()+7)%7;if(!x)x=7;d.setDate(d.getDate()+x);return d.toLocaleDateString('en-CA')};
let cupc=null,uback='core',piupc=null,pitems=[];
async function api(p,o={}){let r=await fetch(p,o),b=null;try{b=await r.json()}catch{}if(!r.ok){let d=b?.detail;throw new Error(typeof d==='string'?d:(d?.reason||'HTTP '+r.status))}return b}
function go(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('on'));$(id).classList.add('on');scrollTo({top:0,behavior:'smooth'})}
function pill(s){s=String(s||'UNKNOWN');let c=s==='READY'?'ok':(s.includes('BLOCK')||s==='QA_HOLD'?'bad':'warn');return '<span class="pill '+c+'">'+esc(s)+'</span>'}
function m(k,v){return '<div class="m"><div class="k">'+esc(k)+'</div><div class="v">'+esc(v)+'</div></div>'}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-main]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-main]').forEach(x=>x.classList.toggle('on',x===b));go(b.dataset.main)});

async function csearch(){let q=$('cq').value.trim();if(!q)return;$('cmsg').textContent='Searching…';$('cres').innerHTML='';try{let d=await api('/v1/app/v2/search?q='+encodeURIComponent(q)+'&limit=30');$('cmsg').textContent=d.count+' result(s)';$('cres').innerHTML=(d.results||[]).map((r,i)=>'<div class="card result" data-i="'+i+'"><div class="row" style="justify-content:space-between"><div class="name">'+esc(r.name)+'</div>'+pill(r.readiness)+'</div><div class="meta">'+esc(r.result_type)+' · '+esc(r.number||'—')+' · '+esc(r.category||'—')+'</div><div class="meta">28 supported-day Qty '+fmt(r.qty_28d)+' '+esc(r.qty_28d_uom||'')+'</div></div>').join('');document.querySelectorAll('#cres .result').forEach(e=>e.onclick=()=>{let r=d.results[+e.dataset.i];r.result_type==='FAMILY'?family(r.family_id||r.number):upc(r.number,'core')})}catch(e){$('cmsg').textContent=e.message}}$('cs').onclick=csearch;$('cq').onkeydown=e=>{if(e.key==='Enter')csearch()};

async function family(k){try{let d=await api('/v1/app/v2/family/'+encodeURIComponent(k)),o=d.current_effective_oh||{},z=d.observed_delivery||{},r=d.last_receipt||{};$('ft').textContent=d.family_article_name;$('fs').textContent='Family '+(d.family_article_number||'—')+' · '+(d.category||'—');$('fsummary').innerHTML='<div class="card"><div class="grid">'+m('Family Article',d.family_article_number||'—')+m('Category',d.category||'—')+m('Effective OH',fmt(o.quantity)+' '+(o.uom||''))+m('Next Expected Delivery',d.next_expected_delivery_date||'Uncertain')+m('Observed Days',(z.observed_delivery_days||[]).map(x=>x.weekday).join(', ')||'—')+m('Frequency',z.frequency||'—')+m('Last Receipt',r.date||'—')+m('Receipt Qty',fmt(r.quantity)+' '+(r.uom||''))+m('Receipt Cost',money(r.cost)+' '+(r.cost_uom||''))+'</div></div>';$('fu').innerHTML=(d.related_upcs||[]).map((x,i)=>'<tr data-i="'+i+'" class="result"><td><b>'+esc(x.name)+'</b><div class="meta">'+esc(x.upc)+'</div></td><td>'+pill(x.readiness)+'</td><td>'+money(x.current_price)+'</td><td>'+esc(x.current_price_type||'—')+'</td><td>'+fmt(x.qty_7d)+'</td><td>'+fmt(x.qty_28d)+'</td></tr>').join('');document.querySelectorAll('#fu tr').forEach(e=>e.onclick=()=>upc(d.related_upcs[+e.dataset.i].upc,'family'));go('family')}catch(e){alert(e.message)}}

async function upc(u,b='core'){try{let d=await api('/v1/app/v2/upc/'+encodeURIComponent(u));cupc=d.upc;uback=b;$('ut').textContent=d.upc_name;$('us').textContent='UPC '+d.upc+' · '+(d.category||'—');$('usum').innerHTML='<div class="grid">'+m('UPC',d.upc)+m('Category',d.category||'—')+m('Price',money(d.current_price)+' '+(d.current_price_type||''))+m('7D Qty',fmt(d.qty_7d?.sold_quantity))+m('28D Qty',fmt(d.qty_28d?.sold_quantity))+m('Family',d.family_article_number||'—')+'</div>';$('uf').onclick=()=>family(d.family_article_number);$('upr').onclick=()=>price(d.upc);$('uo').onclick=()=>corder(d.upc);go('upc')}catch(e){alert(e.message)}}$('ub').onclick=()=>go(uback);

async function price(u){try{let d=await api('/v1/app/v2/upc/'+encodeURIComponent(u)+'/price?trend_supported_days=90'),c=d.current||{},r=d.references||{},s=d.sales||{};$('pt').textContent=d.name;$('ps').textContent='UPC '+d.upc+' · '+(d.category||'—');$('pc').innerHTML='<div class="card"><div class="grid">'+m('Current Price',money(c.price)+' '+(c.price_type||''))+m('Cost',money(c.cost)+' '+(c.cost_uom||''))+m('GP%',c.gp_pct==null?'—':fmt(Number(c.gp_pct)*100,1)+'%')+m('GP$/Day',money(c.gp_per_day_7d))+m('7D Qty',fmt(s['7d']?.sold_quantity))+m('28D Qty',fmt(s['28d']?.sold_quantity))+m('Sweet Spot',money(r.sweet_spot))+m('WGPM',money(r.wgpm))+m('Company A',money(r.company_a))+m('Company B',money(r.company_b))+m('Company C',money(r.company_c))+'</div></div>';chart(d.price_vs_sales_trend?.rows||[]);$('ph').innerHTML=(d.historical_promotions||[]).map(p=>'<div class="promo"><b>'+esc(p.promotion_type)+' Promotion</b><div class="meta">'+esc(p.start_date)+' → '+esc(p.end_date)+' · '+money(p.sale_price)+'</div><div class="meta">'+fmt(p.sale_quantity)+' sold · '+fmt(p.sale_velocity_per_supported_day)+'/supported day · coverage '+fmt(p.supported_sales_day_count,0)+'/'+fmt(p.calendar_duration_days,0)+'</div></div>').join('')||'<div class="small">No historical SALE periods.</div>';go('price')}catch(e){alert(e.message)}}
function chart(rows){let c=$('chart'),x=c.getContext('2d'),R=devicePixelRatio||1,w=Math.max(300,c.clientWidth),h=290;c.width=w*R;c.height=h*R;x.setTransform(R,0,0,R,0,0);x.clearRect(0,0,w,h);let a=rows.slice(-90),p={l:42,r:42,t:18,b:38};if(!a.length){x.fillText('No trend data',20,30);return}let ps=a.map(z=>Number(z.avg_sold_price)).filter(Number.isFinite),qs=a.map(z=>Number(z.sold_quantity)||0),pm=Math.max(...ps,1),qm=Math.max(...qs,1),pw=w-p.l-p.r,ph=h-p.t-p.b,xx=i=>p.l+(a.length===1?0:pw*i/(a.length-1)),yp=v=>p.t+ph*(1-v/pm),yq=v=>p.t+ph*(1-v/qm);x.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');for(let i=0;i<5;i++){let y=p.t+ph*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke()}x.lineWidth=2;x.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ok');x.beginPath();a.forEach((z,i)=>i?x.lineTo(xx(i),yq(Number(z.sold_quantity)||0)):x.moveTo(xx(i),yq(Number(z.sold_quantity)||0)));x.stroke();x.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--a');x.beginPath();let on=false;a.forEach((z,i)=>{let v=Number(z.avg_sold_price);if(!Number.isFinite(v)){on=false;return}if(!on){x.moveTo(xx(i),yp(v));on=true}else x.lineTo(xx(i),yp(v))});x.stroke();x.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--sale');a.forEach((z,i)=>{if((z.price_types||[]).some(v=>v.price_type==='SALE'))x.fillRect(xx(i)-2,h-p.b+6,4,9)})}

async function corder(u){cupc=u;$('cod').value=today();$('cop').value='0';$('cpf').classList.add('hide');try{let d=await api('/v1/app/v2/upc/'+encodeURIComponent(u)+'/ordering');$('cot').textContent=d.family_article_name||d.name;$('cos').textContent='Family '+(d.family_article_number||'—')+' · '+(d.category||'—')+' · from UPC '+(d.source_upc||u);$('cdd').value=d.inputs?.expected_delivery_date||'';corender(d);go('corder')}catch(e){$('coout').innerHTML='<div class="card bad">'+esc(e.message)+'</div>';go('corder')}}$('cop').onchange=()=> $('cpf').classList.toggle('hide',$('cop').value!=='1');$('coa').onclick=async()=>{let q=new URLSearchParams();q.set('ordering_date',$('cod').value);q.set('expected_delivery_date',$('cdd').value);let p=$('cop').value==='1';q.set('promotion_involved',p);if(p){q.set('promotion_start_date',$('cps').value);q.set('promotion_end_date',$('cpe').value);q.set('promotion_price',$('cpp').value)}try{corender(await api('/v1/app/v2/upc/'+encodeURIComponent(cupc)+'/ordering?'+q))}catch(e){$('coout').innerHTML='<div class="card bad">'+esc(e.message)+'</div>'}};
function corender(d){let i=d.inventory||{},f=d.forecast||{},r=d.regular_baseline||{};$('cohist').innerHTML=(d.historical_promotions||[]).slice(0,5).map(p=>'<div class="promo"><b>'+esc(p.promotion_type)+' Promotion</b><div class="meta">'+esc(p.start_date)+' → '+esc(p.end_date)+' · '+money(p.sale_price)+' · '+fmt(p.sale_quantity)+' sold</div></div>').join('');$('coout').innerHTML='<div class="card order"><div class="grid">'+m('Effective OH',fmt(i.raw_effective_oh_qty)+' '+(f.suggested_order_uom||''))+m('OH Used',fmt(i.ordering_oh_qty)+' '+(f.suggested_order_uom||''))+m('Regular Velocity',fmt(r.regular_velocity_per_supported_day))+m('Next Next Delivery',d.next_next_delivery_date||'—')+m('Forecast Usage',fmt(f.forecast_usage_until_next_next_delivery))+m('Projected OH @ Delivery',fmt(f.projected_oh_at_expected_delivery))+'</div><div class="small">Suggested Order Qty</div><div class="big">'+fmt(f.suggested_order_qty)+' '+esc(f.suggested_order_uom||'')+'</div>'+(i.negative_oh_treated_as_zero?'<div class="warn">Negative OH treated as 0 for ordering.</div>':'')+'</div>'}

function orderDefaults(){let t=today();$('od').value=t;$('dd').value=nextwd(t,5)}orderDefaults();$('ot').onchange=()=>{$('dd').value=nextwd($('od').value||today(),$('ot').value==='FRESH'?5:2)};$('od').onchange=()=>$('ot').onchange();$('op').onchange=()=> $('opa').classList.toggle('hide',$('op').value!=='1');
$('ois').onclick=async()=>{let q=$('oiq').value.trim();if(!q)return;try{let d=await api('/v1/app/v2/search?q='+encodeURIComponent(q)+'&limit=20'),f=[],seen=new Set();for(let r of d.results||[]){let k=r.result_type==='FAMILY'?(r.family_id||r.number):(r.family_id||r.family_article_number),n=r.result_type==='FAMILY'?r.number:r.family_article_number,N=r.result_type==='FAMILY'?r.name:r.family_name;if(k&&!seen.has(String(k))){seen.add(String(k));f.push({family_id:r.family_id,family_article_number:n,name:N})}}$('oim').textContent=f.length+' family match(es)';$('oir').innerHTML=f.slice(0,8).map((z,i)=>'<div class="card result" data-i="'+i+'"><b>'+esc(z.name)+'</b><div class="meta">Family '+esc(z.family_article_number||z.family_id)+'</div></div>').join('');document.querySelectorAll('#oir .result').forEach(e=>e.onclick=()=>addPromo(f[+e.dataset.i]))}catch(e){$('oim').textContent=e.message}};
async function addPromo(z){let k=String(z.family_article_number||z.family_id);if(pitems.some(x=>String(x.family_article_number||x.family_id)===k))return;pitems.push({...z,promotion_price:''});drawPromo();$('oir').innerHTML='';$('oiq').value='';try{let d=await api('/v1/app/v2/family/'+encodeURIComponent(k)+'/promotions');$('ohist').innerHTML='<div class="card"><b>Historical SALE · '+esc(z.name)+'</b>'+(d.historical_promotions||[]).slice(0,5).map((p,i)=>'<div class="promo result" data-i="'+i+'"><b>'+esc(p.promotion_type)+'</b><div class="meta">'+p.start_date+' → '+p.end_date+' · '+money(p.sale_price)+'</div><div class="meta">'+fmt(p.sale_quantity)+' sold · '+fmt(p.sale_velocity_per_supported_day)+'/supported day</div></div>').join('')+'</div>';document.querySelectorAll('#ohist .promo').forEach(e=>e.onclick=()=>{let p=d.historical_promotions[+e.dataset.i];let it=pitems.find(x=>String(x.family_article_number||x.family_id)===k);if(it&&p.sale_price!=null)it.promotion_price=Number(p.sale_price).toFixed(2);drawPromo();$('oim').textContent='Historical '+p.promotion_type+' reference selected. Enter the upcoming promotion dates.'})}catch(e){}}
function drawPromo(){$('oil').innerHTML=pitems.length?'<div class="card"><b>Promotion Families</b>'+pitems.map((z,i)=>'<div class="row" style="margin-top:7px"><div class="grow"><b>'+esc(z.name)+'</b><div class="meta">Family '+esc(z.family_article_number||z.family_id)+'</div></div><input data-p="'+i+'" placeholder="SALE price" value="'+esc(z.promotion_price)+'" style="max-width:110px"><button data-r="'+i+'">Remove</button></div>').join('')+'</div>':'';document.querySelectorAll('[data-p]').forEach(e=>e.oninput=()=>pitems[+e.dataset.p].promotion_price=e.value);document.querySelectorAll('[data-r]').forEach(e=>e.onclick=()=>{pitems.splice(+e.dataset.r,1);drawPromo()})}
$('ogen').onclick=async()=>{let promo=$('op').value==='1',body={order_type:$('ot').value,ordering_date:$('od').value,expected_delivery_date:$('dd').value,promotion_involved:promo,promotion_start_date:promo?$('ops').value:null,promotion_end_date:promo?$('ope').value:null,promotion_items:promo?pitems.map(x=>({family_article_number:x.family_article_number||null,family_id:x.family_id||null,promotion_price:x.promotion_price||null})):[]};$('omsg').textContent='Calculating…';try{let d=await api('/v1/app/v2/ordering/suggestions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('omsg').textContent=d.suggestion_count+' suggestion(s) · next-next '+(d.inputs?.next_next_delivery_date||'—');$('ores').innerHTML=(d.suggestions||[]).map(r=>'<div class="card order"><div class="row" style="justify-content:space-between"><div><div class="name">'+esc(r.family_article_name)+'</div><div class="meta">Family '+esc(r.family_article_number)+' · '+esc(r.category)+(r.promotion_involved?' · SALE':'')+'</div></div>'+pill(r.readiness)+'</div><div class="grid" style="margin-top:8px">'+m('DOS',fmt(r.dos,1))+m('Effective OH',fmt(r.effective_oh_raw)+' '+r.uom)+m('OH Used',fmt(r.ordering_oh_used)+' '+r.uom)+m('28D Qty',fmt(r.qty_28d))+m('Forecast',fmt(r.forecast_total_usage))+m('Projected OH @ Delivery',fmt(r.projected_oh_at_delivery))+'</div><div class="small">Suggested Order Qty</div><div class="big">'+fmt(r.suggested_order_qty)+' '+esc(r.suggested_order_uom||'')+'</div></div>').join('')||'<div class="card small">No family meets Active 28 supported-day selling + DOS &lt; 7.</div>'}catch(e){$('omsg').textContent=e.message}};

async function pisearch(){let q=$('piq').value.trim();if(!q)return;try{let d=await api('/v1/app/v2/pi/search?q='+encodeURIComponent(q)+'&limit=30');$('pim').textContent=d.count+' inventory owner(s)';$('pir').innerHTML=(d.results||[]).map((r,i)=>'<div class="card result" data-i="'+i+'"><div class="row" style="justify-content:space-between"><div class="name">'+esc(r.owner_name||r.representative_upc_name)+'</div>'+pill(r.readiness)+'</div><div class="meta">'+esc(r.owner_scope)+' #'+esc(r.owner_id)+' · Family '+esc(r.family_article_number||'—')+'</div><div class="meta">System OH '+fmt(r.system_oh?.quantity)+' '+esc(r.system_oh?.uom||'')+' · Effective OH '+fmt(r.effective_oh?.quantity)+' '+esc(r.effective_oh?.uom||'')+'</div></div>').join('');document.querySelectorAll('#pir .result').forEach(e=>e.onclick=()=>pid(d.results[+e.dataset.i].representative_upc))}catch(e){$('pim').textContent=e.message}}$('pis').onclick=pisearch;$('piq').onkeydown=e=>{if(e.key==='Enter')pisearch()};
async function pid(u){try{let d=await api('/v1/app/v2/pi/'+encodeURIComponent(u)),s=d.system_oh||{},f=d.effective_oh||{},x=d.current_discrepancy||{},r=d.last_receipt||{};piupc=d.identity?.upc;$('pit').textContent=d.inventory_owner?.owner_name||d.identity?.upc_name;$('pisub').textContent=(d.inventory_owner?.scope||'')+' #'+(d.inventory_owner?.owner_id||'')+' · '+(d.identity?.category||'');$('pisum').innerHTML='<div class="card"><div class="grid">'+m('System OH',fmt(s.quantity)+' '+(s.uom||''))+m('Effective OH',fmt(f.quantity)+' '+(f.uom||''))+m('OH Source',f.source||'—')+m('OH Snapshot',s.snapshot_date||'—')+m('Current Difference',fmt(x.signed_difference_true_minus_system)+' '+(x.uom||''))+m('Last Receipt',r.posting_date||'—')+'</div></div>';$('puom').value=d.required_true_stock_uom||'';$('pqty').value='';$('pnote').value='';$('pih').innerHTML=(d.true_stock_history||[]).map(h=>'<tr><td>'+esc(h.submitted_at||'')+'</td><td>'+fmt(h.system_oh_quantity)+' '+esc(h.uom||'')+'</td><td>'+fmt(h.true_stock_quantity)+' '+esc(h.uom||'')+'</td><td>'+fmt(h.signed_difference_true_minus_system)+'</td><td>'+esc(h.status||'')+'</td><td>'+esc(h.count_note||'')+'</td></tr>').join('');go('pid')}catch(e){alert(e.message)}}$('papply').onclick=async()=>{let q=$('pqty').value.trim(),u=$('puom').value;if(q===''||!u)return;try{let d=await api('/v1/app/v2/pi/'+encodeURIComponent(piupc)+'/true-stock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({true_stock:q,uom:u,note:$('pnote').value||null})});await pid(piupc);$('pamsg').className='msg success';$('pamsg').textContent='Applied · difference '+fmt(d.signed_difference_true_minus_system)+' '+u+' · shortage '+fmt(d.shortage_quantity)+' · overage '+fmt(d.overage_quantity)}catch(e){$('pamsg').className='msg bad';$('pamsg').textContent=e.message}};
</script></body></html>"""

